1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	// The CLAIM_ prefix marks the claim-side pair. Both are deliberately distinct
14	// from their premium-side namesakes above: a sword can be enchanted enough to
15	// cost more to insure (threshold 5) without being enchanted enough to pay out
16	// less (threshold 8).
17	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
18	const CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
19	
20	const BASE_PREMIUMS = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	} as const;
28	
29	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
30	// claims is derived from these, so premium discounts never move it.
31	const INSURANCE_VALUES = {
32	  sword: 1000,
33	  amulet: 600,
34	  staff: 800,
35	  potion: 400,
36	  rune: 250,
37	  moonstone: 250,
38	} as const;
39	
40	// The six priced types are the domain, so they are derived from the premium
41	// table rather than restated: a type nobody prices cannot be insured. The
42	// unknown-type case (broomstick) is still a runtime error the tests will drive.
43	type ItemType = keyof typeof BASE_PREMIUMS;
44	
45	// Components (as opposed to main items) are the only things the block rule
46	// applies to, so the distinction has to be data, not a price coincidence.
47	// Typed as a set of ItemType so a component can never name an unpriced type.
48	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
49	
50	const PERCENT_WHOLE = 100;
51	
52	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
53	// floating-point error that shifts the spec's round-up in MHPCO's favour.
54	const percentOf = (percent: number, amount: number): number =>
55	  (amount * percent) / PERCENT_WHOLE;
56	
57	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
58	// round up, payouts (MHPCO pays) round down.
59	const roundPremiumInMHPCOsFavour = Math.ceil;
60	
61	export type QuoteResult = { premium: number };
62	
63	export type ClaimResult = { payout: number; remainingCap: number };
64	
65	export type ScenarioResult = QuoteResult | ClaimResult;
66	
67	// `material` is accepted but never read: the dragon-material clause reimburses
68	// in full, which is what every ordinary item already gets, so no code can yet
69	// tell dragon from steel. See `reimbursableAmountFor`. All three are optional so
70	// a bare `{ type: "rune" }` typechecks: a rune has no enchantment to speak of,
71	// rather than an enchantment of zero.
72	type Item = {
73	  type: ItemType;
74	  material?: string;
75	  enchantment?: number;
76	  cursed?: boolean;
77	};
78	
79	type Damage = { itemType: string; amount: number };
80	
81	type Incident = { cause: string; damages: Damage[] };
82	
83	type QuoteStep = { op: "quote"; items: Item[] };
84	
85	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
86	
87	type Step = QuoteStep | ClaimStep;
88	
89	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
90	
91	type Customer = { yearsWithMHPCO: number };
92	
93	type Scenario = {
94	  customer: Customer;
95	  steps: Step[];
96	};
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// The ItemType union is compile-time only, and scenarios arrive as parsed JSON,
102	// so an unknown type has to be caught here rather than trusted. Without this the
103	// missing table entry would quietly poison the arithmetic with NaN.
104	const basePremiumForItem = (item: Item): number => {
105	  const basePremium = BASE_PREMIUMS[item.type];
106	  if (basePremium === undefined) {
107	    throw new Error(`MHPCO does not insure items of type ${item.type}`);
108	  }
109	  return basePremium;
110	};
111	
112	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
113	
114	// Groups of items that are "alike" — same type. The type is kept alongside the
115	// items because the block rule asks about it; recovering it from items[0] would
116	// make every reader re-derive that a group is non-empty and homogeneous.
117	type AlikeItems = { type: ItemType; items: Item[] };
118	
119	const groupByType = (items: Item[]): AlikeItems[] => {
120	  const groups = new Map<ItemType, Item[]>();
121	  for (const item of items) {
122	    const group = groups.get(item.type) ?? [];
123	    group.push(item);
124	    groups.set(item.type, group);
125	  }
126	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
127	};
128	
129	// A block is a discount on the components' combined base premium, not a flat
130	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
131	// 20 % stays visible as the rule it is.
132	const blockBasePremium = (items: Item[]): number => {
133	  const undiscounted = sumBasePremiums(items);
134	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
135	};
136	
137	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
138	// pile is never cheaper than the block it contains. Components only — three
139	// swords are three separate insurances, not a discounted building block.
140	const formsABlock = ({ type, items }: AlikeItems): boolean =>
141	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
142	
143	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
144	  formsABlock(alikeItems)
145	    ? blockBasePremium(alikeItems.items)
146	    : sumBasePremiums(alikeItems.items);
147	
148	// Priced per group of alike items rather than over the whole list, so 3 runes
149	// and 3 moonstones each form their own block.
150	const policyBasePremiumFor = (items: Item[]): number =>
151	  sum(groupByType(items).map(basePremiumForGroup));
152	
153	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
154	  applies ? percentOf(percent, amount) : 0;
155	
156	// Each item-specific surcharge is a percentage of the affected item's OWN base
157	// premium, so every rule reads as "this much, when this holds". The terms are
158	// summed rather than chosen between: an item can trigger several at once.
159	//
160	// Deliberately two explicit terms rather than a table of rules. The shared
161	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
162	// a threshold over an optional number), and nothing in the remaining spec adds
163	// a third item-specific surcharge to generalise over.
164	const surchargeFor = (item: Item): number => {
165	  const base = basePremiumForItem(item);
166	  return (
167	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
168	    percentOfWhen(
169	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
170	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
171	      base,
172	    )
173	  );
174	};
175	
176	// Charged alongside the policy base premium — never folded into it, or the
177	// policy-wide modifiers would compound on top of them.
178	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
179	
180	// Unlike the item-specific surcharges, these are percentages of the WHOLE
181	// policy's base premium. Each is returned already signed — a surcharge is
182	// positive, a discount negative — so the rule and its direction stay on one
183	// line instead of the sign living in a `+`/`-` further down the sum.
184	const policyModifiersFor = (
185	  policyBasePremium: number,
186	  customer: Customer,
187	  isFollowUpContract: boolean,
188	): number[] => [
189	  // Applies to every quote, follow-ups included: the spec treats each item in a
190	  // quote as newly insured, regardless of how long the customer has been around.
191	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
192	  -percentOfWhen(
193	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
194	    LOYALTY_DISCOUNT_PERCENT,
195	    policyBasePremium,
196	  ),
197	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
198	];
199	
200	// The order of the terms is the order of the spec's rules: what the items are
201	// worth, what they individually cost extra, what the policy as a whole is
202	// adjusted by, and MHPCO's fee on top.
203	const quoteFor = (
204	  items: Item[],
205	  customer: Customer,
206	  isFollowUpContract: boolean,
207	): QuoteResult => {
208	  const policyBasePremium = policyBasePremiumFor(items);
209	  const premium = roundPremiumInMHPCOsFavour(
210	    policyBasePremium +
211	      itemSurchargesFor(items) +
212	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
213	      PROCESSING_FEE,
214	  );
215	  return { premium };
216	};
217	
218	// A follow-up contract is any quote after the customer's first, so what counts
219	// is how many QUOTES precede this step — not how many steps do. Claim steps sit
220	// in the same list and must not push a later quote into follow-up territory.
221	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
222	  precedingSteps.some(isQuote);
223	
224	const insuranceSumFor = (items: Item[]): number =>
225	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
226	
227	// MHPCO pays, so payouts round down.
228	const roundPayoutInMHPCOsFavour = Math.floor;
229	
230	// How much of a damage the policy reimburses, before the deductible. The
231	// clauses are CHOSEN BETWEEN, not summed — unlike the premium surcharges, where
232	// a cursed AND highly-enchanted sword pays both. Written as a chain of
233	// exceptions over a default so precedence is the reading order: the first
234	// matching clause wins.
235	//
236	// Only one exception is listed. Dragon material is the spec's other clause, but
237	// it reimburses in full, which is already the default — so it is deliberately
238	// absent rather than written as a branch returning `damage.amount` unchanged.
239	// A conditional whose arms agree hides that agreement instead of stating it,
240	// and suggests the material is doing work here when it is not. It earns a
241	// branch on the day a test makes dragon differ from ordinary steel.
242	const reimbursableAmountFor = (damage: Damage, damagedItem: Item): number => {
243	  // Negative damage would have MHPCO billing the customer for being attacked.
244	  // Zero is allowed: a scratch below the deductible is a real, if futile, claim.
245	  if (damage.amount < 0) {
246	    throw new Error(`Claim reports a damage of ${damage.amount} G, which cannot be negative`);
247	  }
248	  return (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
249	    ? percentOf(CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
250	    : damage.amount;
251	};
252	
253	// A damage entry together with the insured item it was matched to. Pairing them
254	// in one value keeps the two from being re-joined by position further down,
255	// where the correctness of the join would rest on an unstated shared ordering.
256	type DamagedItem = { damage: Damage; item: Item };
257	
258	// Each damage entry carries its own deductible: one dragon attack damaging two
259	// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
260	// clauses apply to the damage amount FIRST, so the deductible bites last.
261	const payoutForDamage = ({ damage, item }: DamagedItem): number =>
262	  reimbursableAmountFor(damage, item) - DEDUCTIBLE;
263	
264	// Splits the insured items into the first one of the wanted type and the rest.
265	// A damage with nothing left to match is a claim on something MHPCO never
266	// insured, which voids the whole claim.
267	const claimOneItemOfType = (
268	  itemType: string,
269	  unclaimed: Item[],
270	): { item: Item; stillUnclaimed: Item[] } => {
271	  const index = unclaimed.findIndex((insured) => insured.type === itemType);
272	  if (index === -1) {
273	    throw new Error(`Claim damages a ${itemType} beyond what this policy covers`);
274	  }
275	  return {
276	    item: unclaimed[index],
277	    stillUnclaimed: unclaimed.filter((_, position) => position !== index),
278	  };
279	};
280	
281	// Pairs each damage entry with the insured item it refers to. An item can only
282	// be damaged once per incident, so entries CONSUME the items they match: two
283	// sword damages need two insured swords. The fold carries the not-yet-matched
284	// items from one entry to the next, which is what makes the consumption a
285	// property of the traversal rather than a side effect on a scratch array.
286	const damagedItemsFor = (damages: Damage[], insuredItems: Item[]): DamagedItem[] =>
287	  damages.reduce<{ damagedItems: DamagedItem[]; unclaimed: Item[] }>(
288	    ({ damagedItems, unclaimed }, damage) => {
289	      const { item, stillUnclaimed } = claimOneItemOfType(damage.itemType, unclaimed);
290	      return {
291	        damagedItems: [...damagedItems, { damage, item }],
292	        unclaimed: stillUnclaimed,
293	      };
294	    },
295	    { damagedItems: [], unclaimed: insuredItems },
296	  ).damagedItems;
297	
298	// The cap is a property of the POLICY, not of the claim: twice what the policy's
299	// items are insured for. Kept separate from the payout so the cross-claim
300	// accumulation the spec still demands has an obvious place to attach.
301	const capFor = (policy: QuoteStep): number =>
302	  insuranceSumFor(policy.items) * CAP_MULTIPLE;
303	
304	// The cap is spent down across every claim on a policy rather than reset per
305	// claim, so the caller supplies what is left; a claim wanting more than remains
306	// is cut short by it.
307	const claimFor = (claim: ClaimStep, policy: QuoteStep, capRemaining: number): ClaimResult => {
308	  const damagedItems = damagedItemsFor(claim.incident.damages, policy.items);
309	  const payoutBeforeCap = roundPayoutInMHPCOsFavour(
310	    sum(damagedItems.map(payoutForDamage)),
311	  );
312	  const payout = Math.min(payoutBeforeCap, capRemaining);
313	  return { payout, remainingCap: capRemaining - payout };
314	};
315	
316	// `claim.policy` indexes the scenario's steps, and the referenced step must be a
317	// quote — a claim against a claim is meaningless. Nothing validates the scenario
318	// yet, so this states the assumption instead of casting past it; the
319	// error-case tests will turn the throw into a reported error.
320	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
321	  const step = steps[claim.policy];
322	  if (step === undefined || !isQuote(step)) {
323	    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
324	  }
325	  return step;
326	};
327	
328	// What a policy has left to pay out, keyed by the step index that quoted it.
329	// A policy absent from the map has had no claims yet, so its remaining cap is
330	// still the full `capFor` — the map records spending, not entitlement.
331	type CapRemainingByPolicy = ReadonlyMap<number, number>;
332	
333	// Everything the scenario carries FORWARD from one step to the next. Results
334	// accumulate; caps are spent down. Naming it makes the fold below a transition
335	// between two of these rather than bookkeeping over loose variables.
336	type ScenarioProgress = {
337	  results: ScenarioResult[];
338	  capRemainingByPolicy: CapRemainingByPolicy;
339	};
340	
341	const withCapRemaining = (
342	  capRemainingByPolicy: CapRemainingByPolicy,
343	  policyIndex: number,
344	  capRemaining: number,
345	): CapRemainingByPolicy =>
346	  new Map(capRemainingByPolicy).set(policyIndex, capRemaining);
347	
348	// A claim reads the cap its policy has left and hands back what remains, so it
349	// is the only step kind that advances more than the results list.
350	const claimStepResult = (
351	  step: ClaimStep,
352	  steps: Step[],
353	  capRemainingByPolicy: CapRemainingByPolicy,
354	): { result: ClaimResult; capRemainingByPolicy: CapRemainingByPolicy } => {
355	  const policy = policyReferencedBy(step, steps);
356	  const capRemaining = capRemainingByPolicy.get(step.policy) ?? capFor(policy);
357	  const result = claimFor(step, policy, capRemaining);
358	  return {
359	    result,
360	    capRemainingByPolicy: withCapRemaining(
361	      capRemainingByPolicy,
362	      step.policy,
363	      result.remainingCap,
364	    ),
365	  };
366	};
367	
368	// A quote depends only on the steps BEFORE it (to spot a follow-up contract),
369	// never on what later steps do, so it leaves the caps untouched.
370	const quoteStepResult = (
371	  step: QuoteStep,
372	  precedingSteps: Step[],
373	  customer: Customer,
374	): QuoteResult => quoteFor(step.items, customer, isFollowUpContract(precedingSteps));
375	
376	// A fold rather than a map: claims spend a shared cap, so a step's result
377	// depends on the steps before it. `reduce` says that in the signature — `map`
378	// would promise each step is independent and then quietly break the promise.
379	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
380	  const { results } = scenario.steps.reduce<ScenarioProgress>(
381	    (progress, step, stepIndex) => {
382	      if (isQuote(step)) {
383	        const result = quoteStepResult(
384	          step,
385	          scenario.steps.slice(0, stepIndex),
386	          scenario.customer,
387	        );
388	        return { ...progress, results: [...progress.results, result] };
389	      }
390	      const { result, capRemainingByPolicy } = claimStepResult(
391	        step,
392	        scenario.steps,
393	        progress.capRemainingByPolicy,
394	      );
395	      return { results: [...progress.results, result], capRemainingByPolicy };
396	    },
397	    { results: [], capRemainingByPolicy: new Map() },
398	  );
399	  return { results };
400	};
401

