85	  it("3 runes → 60 G base premium (block applies)", () => {
86	    // base 60 + 6 first insurance + 5 fee = 71 G
87	    const result = runScenario({
88	      customer: { yearsWithMHPCO: 0 },
89	      steps: [
90	        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
91	      ],
92	    });
93	
94	    expect(result).toEqual({ results: [{ premium: 71 }] });
95	  });
96	  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
97	    // base 100 + 10 first insurance + 5 fee = 115 G
98	    const result = runScenario({
99	      customer: { yearsWithMHPCO: 0 },
100	      steps: [
101	        {
102	          op: "quote",
103	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
104	        },
105	      ],
106	    });
107	
108	    expect(result).toEqual({ results: [{ premium: 115 }] });
109	  });
110	  it("7 runes → 175 G base premium", () => {
111	    // base 175 + 17.5 first insurance + 5 fee = 197.5 → 198 G
112	    const result = runScenario({
113	      customer: { yearsWithMHPCO: 0 },
114	      steps: [
115	        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
116	      ],
117	    });
118	
119	    expect(result).toEqual({ results: [{ premium: 198 }] });
