121	
122	  // --- "Alike" components means same type ---
123	  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
124	    // base 75 + 7.5 first insurance + 5 fee = 87.5 → 88 G
125	    const result = runScenario({
126	      customer: { yearsWithMHPCO: 0 },
127	      steps: [
128	        {
129	          op: "quote",
130	          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
131	        },
132	      ],
133	    });
