137	  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
138	    // base 60 + 60 = 120, + 12 first insurance + 5 fee = 137 G
139	    const result = runScenario({
140	      customer: { yearsWithMHPCO: 0 },
141	      steps: [
142	        {
143	          op: "quote",
144	          items: [
145	            { type: "rune" },
146	            { type: "rune" },
147	            { type: "rune" },
148	            { type: "moonstone" },
149	            { type: "moonstone" },
150	            { type: "moonstone" },
151	          ],
152	        },
153	      ],
154	    });
155	
156	    expect(result).toEqual({ results: [{ premium: 137 }] });
157	  });
158	
159	  it("3 swords → 300 G base premium (no block — the block is a components-only rule)", () => {
